var i=`0218-tarta-de-santiago`;var t=`world-0218`;var a=`ES`;var o=`southern-europe`;var s=8;var r=47;var g={en:`Tarta de Santiago`,ua:`Торт Сантьяго`};var d={en:`A traditional Spain dish made with almond flour, chicken egg, lemon zest. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: мигдалеве борошно, куряче яйце, цедра лимона. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var l=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`almond-flour`,250,`g`],[`white-granulated-sugar`,195,`g`],[`chicken-egg`,4,`pcs`],[`lemon-zest`,5,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Bake in a preheated 180°C oven for about 37 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 37 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:37,i:[[`unsalted-butter`,10,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,25,`g`]]}];var u={slug:i,id:t,country:`ES`,region:o,servings:8,minutes:47,title:g,text:d,steps:l};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,i as slug,l as steps,d as text,g as title};